const API='https://equran.id/api/v2';let surahs=[],shown=12;const $=id=>document.getElementById(id);function normalizeSurah(x){return[x.nomor,x.namaLatin,x.arti,x.nama,`${x.jumlahAyat} Ayat · ${String(x.tempatTurun||'').toLowerCase()==='mekah'?'Makkiyah':'Madaniyah'}`]}function card(s){return`<a class="surah" href="surah-v4.html?surah=${s[0]}"><div class="num">${String(s[0]).padStart(2,'0')}</div><div><h4>${s[1]}</h4><div class="meaning">${s[2]}</div><div class="meta">${s[4]}</div></div><div class="arabic">${s[3]}</div></a>`}function filtered(){const f=$('filter').value;return f==='Semua'?surahs:surahs.filter(s=>s[4].includes(f))}function render(){const list=filtered(),v=list.slice(0,shown);$('surahGrid').innerHTML=v.length?v.map(card).join(''):'<div class="surah-loading">Surah tidak ditemukan.</div>';$('surahCount').textContent=`${list.length} surah`;$('loadBtn').style.display=shown>=list.length?'none':'block';lucide.createIcons()}async function init(){try{const r=await fetch(`${API}/surat`),j=await r.json();surahs=(j.data||[]).map(normalizeSurah);render()}catch(e){$('surahGrid').innerHTML='<div class="surah-loading">Daftar surah belum dapat dimuat. Coba refresh halaman.</div>'}setupLast()}function loadMore(){shown+=12;render()}$('filter').onchange=()=>{shown=12;render()};function goSurah(id,ayat){location.href=`surah-v4.html?surah=${id}${ayat?`&ayat=${ayat}`:''}`}function setupLast(){const x=JSON.parse(localStorage.getItem('l6q-last')||'null');if(x)$('lastReadText').textContent=`${x.name||'Surah'} · Ayat ${x.ayat||1}`}function openLastRead(){const x=JSON.parse(localStorage.getItem('l6q-last')||'null');goSurah(x?.surah||2,x?.ayat||1)}function setQuery(v){$('searchInput').value=v;runSearch()}document.querySelectorAll('.finder-example').forEach(b=>b.onclick=()=>setQuery(b.dataset.q));$('searchBtn').onclick=runSearch;$('searchInput').onkeydown=e=>{if(e.key==='Enter')runSearch()};function esc(x){return String(x||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function local(q){q=q.toLowerCase();return surahs.filter(s=>`${s[0]} ${s[1]} ${s[2]} ${s[3]}`.toLowerCase().includes(q)).slice(0,6)}function showLocal(rows){$('searchResults').classList.add('show');$('searchResults').innerHTML=`<div class="result-head"><span>Surah yang cocok</span><span>${rows.length} hasil</span></div>`+rows.map(s=>`<div class="result-item" onclick="goSurah(${s[0]})"><div><div class="result-title">${s[1]}</div><div class="result-sub">${s[2]} · ${s[4]}</div></div><div class="result-arabic">${s[3]}</div></div>`).join('')}async function runSearch(){const q=$('searchInput').value.trim();if(!q)return;const ref=q.match(/^\s*(\d{1,3})\s*[:.]\s*(\d{1,3})\s*$/);if(ref)return goSurah(+ref[1],+ref[2]);const m=local(q);if(m.length)return showLocal(m);$('searchResults').classList.add('show');$('searchResults').innerHTML='<div class="finder-status">Mencari ayat dan tafsir yang relevan...</div>';try{const r=await fetch('https://equran.id/api/vector',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:q,limit:6,types:['ayat','tafsir'],minScore:.25})}),j=await r.json(),rows=j.hasil||[];$('searchResults').innerHTML=`<div class="result-head"><span>Hasil untuk “${esc(q)}”</span><span>${rows.length} hasil</span></div>`+(rows.length?rows.map(x=>{const d=x.data||{},s=d.id_surat||d.nomor_surat,a=d.nomor_ayat||d.ayat,title=x.tipe==='tafsir'?`Tafsir ${d.nama_surat||'Surah'} · Ayat ${a}`:`${d.nama_surat||'Surah'} · Ayat ${a}`,sub=x.tipe==='tafsir'?d.isi:(d.terjemahan_id||d.teks_latin),ar=d.teks_arab||'';return`<div class="result-item" onclick="goSurah(${s},${a})"><div><div class="result-title">${esc(title)}</div><div class="result-sub">${esc(String(sub||'').slice(0,170))}</div></div><div>${ar?`<div class="result-arabic">${ar}</div>`:''}<span class="result-type">${x.tipe}</span></div></div>`}).join(''):'<div class="finder-status">Belum menemukan hasil. Coba kata lain.</div>')}catch(e){$('searchResults').innerHTML='<div class="finder-status">Pencarian topik sedang tidak tersedia. Anda tetap dapat mencari nama surah atau nomor ayat.</div>'}}const pop=['DPR Pertanyakan Kesiapan Anggaran Terkait Putusan MK Gratiskan SD-SMP','Gelombang Tinggi Pesisir Selatan Banten Capai 4 Meter, BMKG Minta Warga Waspada','Prediksi Harga Emas 2 Juni 2025, Siap-Siap Melesat','DPR Pertanyakan Kesiapan Anggaran Terkait Putusan MK Gratiskan SD-SMP','Wakil Ketua MPR Tegaskan Perusahaan Tambang yang Rusak Kawasan Wisata Harus Di-blacklist Selamanya'];$('popular').innerHTML=Array.from({length:10},(_,i)=>`<div class="popular-item"><div class="rank">${i+1}</div><div class="popular-copy"><b>${pop[i%5]}</b><span class="timeago">5 menit lalu</span></div></div>`).join('');const header=document.querySelector('.header'),channel=document.querySelector('.channel-nav'),spacer=$('headerSpacer');let lastY=scrollY;addEventListener('scroll',()=>{const y=scrollY,up=y<lastY;if(y<8){header.classList.remove('is-returning');channel.classList.remove('is-sticky');spacer.classList.remove('active')}else if(up){channel.classList.remove('is-sticky');header.classList.add('is-returning');spacer.classList.add('active')}else{header.classList.remove('is-returning');spacer.classList.remove('active');if(y>128)channel.classList.add('is-sticky')}lastY=y},{passive:true});init();lucide.createIcons();